export function creatureArt(id, {size=160, flip=false}={}) {
  const c = CREATURE_ART[id] || CREATURE_ART.bud;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${Number(size)||160}" height="${Number(size)||160}" viewBox="0 0 200 180" role="img" aria-label="${esc(c.name)}" class="creature-art"><ellipse cx="100" cy="158" rx="56" ry="10" fill="#071e2b" opacity=".18"/><g stroke="${INK}" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" ${flip?'transform="translate(200 0) scale(-1 1)"':''}>${c.body}</g><g fill="${c.color}" opacity=".6"><path d="m25 34 2-5 2 5 5 2-5 2-2 5-2-5-5-2Zm145 105 2-5 2 5 5 2-5 2-2 5-2-5-5-2Z"/></g></svg>`;
}

const palettes = {
  town: ['#123447','#2c665e','#458879','#a6c6a0'],
  forest: ['#112e3c','#1e5149','#2f7360','#7ea874'],
  coast: ['#12364b','#256876','#539a9a','#d6c79b'],
  quarry: ['#202d45','#49576a','#71837f','#b3ae91'],
  summit: ['#182a45','#34485e','#647783','#b5c6ba']
};
const tree = (x,y,s=1,color='#3d846b') => `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cy="20" rx="24" ry="9" fill="#091f2b" opacity=".2"/><path d="M-4 0v25h8V0" fill="#8a8170"/><path d="M0-51C-18-46-28-27-20-18c-24 21-6 37 19 30 30 10 45-10 23-27C32-30 16-47 0-51Z" fill="${color}" stroke="#163e42" stroke-width="2"/><path d="M0-32v36m0-16-14-8M0-7l15-10" fill="none" stroke="#85b895" stroke-width="2" opacity=".4"/></g>`;
const rock = (x,y,s=1) => `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cy="12" rx="28" ry="9" fill="#132a37" opacity=".3"/><path d="m-27 7 7-24 25-9 23 16 5 20-35 9Z" fill="#809590" stroke="#314f5b" stroke-width="2"/><path d="m-20-17 18 13 7-22m-7 22 28-5M-2-4l-3 22" fill="none" stroke="#a9b7a4" stroke-width="2"/></g>`;
